import { defineConfig } from "@hey-api/openapi-ts"

// The client is generated from the backend's OpenAPI document (`npm run api:openapi` writes it
// from `quai openapi`). Never edit src/api/generated by hand: regenerate with `npm run api:gen`;
// CI fails when either is out of date.
export default defineConfig({
  input: "./openapi.json",
  output: { path: "src/api/generated" },
  plugins: ["@hey-api/client-fetch", "@tanstack/react-query"],
})
